  ('00000000-0000-4000-8000-000000003007', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001005', 'Хар хөх жинс', 'Хар хөх өнгийн шулуун жинс. Бүсэлхий W32, урт L32.', 55000, 'M', 'excellent', true, true, '2026-10-30T06:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003008', '00000000-0000-4000-8000-000000002003', '00000000-0000-4000-8000-000000001007', 'Бор арьсан мөрний цүнх', 'Жинхэнэ арьсан бор цүнх, металл түгжээтэй. Тохируулдаг оосортой.', 88000, 'Нэг хэмжээ', 'excellent', true, true, '2026-10-30T05:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003009', '00000000-0000-4000-8000-000000002004', '00000000-0000-4000-8000-000000001004', 'Цөцгий өнгийн hoodie', 'Зөөлөн цөцгий өнгийн, дотроо хөвөнтэй hoodie. Урд том халаастай.', 62000, 'M', 'excellent', true, true, '2026-10-30T04:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003010', '00000000-0000-4000-8000-000000002003', '00000000-0000-4000-8000-000000001002', 'Шалбаа ногоон цамц', 'Зөөлөн шалбаа ногоон өнгийн чөлөөтэй цамц. Өдөр тутам, ажилд аль алинд нь зохино.', 38000, 'S', 'excellent', true, true, '2026-10-30T03:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003011', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001006', 'Цагаан пүүз', 'Цэвэрхэн цагаан пүүз. Аливаа хувцастай зохицно. Хэмжээ EU 40.', 85000, '40', 'excellent', true, true, '2026-10-30T02:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003012', '00000000-0000-4000-8000-000000002004', '00000000-0000-4000-8000-000000001008', 'Ногоон сүлжмэл малгай', 'Хөвд ногоон өнгийн зөөлөн сүлжмэл малгай. Шинэ, шошготой.', 15000, 'Нэг хэмжээ', 'new', true, true, '2026-10-30T01:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003013', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001001', 'Хар саарал hoodie', 'Хар саарал өнгийн зузаан hoodie. Чөлөөтэй, том загвартай.', 60000, 'XL', 'excellent', true, true, '2026-10-30T00:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003014', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001001', 'Хар саарал пальто', 'Сонгодог загварын хар саарал ноосон пальто. Доторлогоо бүтэн.', 160000, 'L', 'good', true, true, '2026-10-29T23:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003015', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001007', 'Даавуун тоут цүнх', 'Зузаан цагаан даавуун тоут цүнх. Шинэ.', 18000, 'Нэг хэмжээ', 'new', true, true, '2026-10-29T22:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003016', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001004', 'Шалбаа ногоон свитшот', 'Зөөлөн шалбаа ногоон өнгийн дугуй захтай свитшот. Ханцуй, хормойдоо резин сүлжээтэй.', 45000, 'M', 'excellent', true, true, '2026-10-29T21:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003017', '00000000-0000-4000-8000-000000002003', '00000000-0000-4000-8000-000000001004', 'Шар ногоон hoodie', 'Тод шар ногоон өнгийн hoodie — анхаарал татах нэг ширхэг. Шинэ, шошготой.', 69000, 'M', 'new', true, true, '2026-10-29T20:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003018', '00000000-0000-4000-8000-000000002004', '00000000-0000-4000-8000-000000001002', 'Цөцгий кардиган', 'Цөцгий өнгийн зөөлөн сүлжмэл кардиган. Бага зэрэг элэгдэлтэй.', 68000, 'S', 'good', true, true, '2026-10-29T19:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003019', '00000000-0000-4000-8000-000000002001', '00000000-0000-4000-8000-000000001005', 'Хаки өмд', 'Шулуун загвартай хаки өмд. Ажил, өдөр тутамд өмсөхөд тохиромжтой.', 45000, 'M', 'excellent', true, true, '2026-10-29T18:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003020', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001008', 'Хар саарал бейсболк', 'Ар талдаа тохируулагчтай хар саарал бейсболк.', 20000, 'Нэг хэмжээ', 'excellent', true, true, '2026-10-29T17:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003021', '00000000-0000-4000-8000-000000002003', '00000000-0000-4000-8000-000000001004', 'Тэмээн өнгийн hoodie', 'Дулаан тэмээн бор өнгийн hoodie. Өнгө нь гандаагүй.', 64000, 'M', 'excellent', true, true, '2026-10-29T16:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003022', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001003', 'Хар бомбер куртик', 'Хар өнгийн хөнгөн бомбер. Ханцуйн үзүүрт бага зэрэг элэгдэлтэй.', 89000, 'L', 'good', true, true, '2026-10-29T15:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003023', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001004', 'Энгийн цагаан футболк', 'Зузаан хөвөн даавуун цагаан футболк. Шинэ, шошготой.', 22000, 'M', 'new', true, true, '2026-10-29T14:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003024', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001005', 'Цайвар жинс', 'Цайвар цэнхэр, шулуун загвартай жинс. Бүсэлхий W33.', 52000, 'L', 'good', true, true, '2026-10-29T13:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003025', '00000000-0000-4000-8000-000000002002', '00000000-0000-4000-8000-000000001004', 'Шалбаа ногоон hoodie', 'Цайвар шалбаа ногоон hoodie. Нэг улирал өмссөн, цэвэрхэн.', 58000, 'S', 'excellent', true, true, '2026-10-29T12:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003026', '00000000-0000-4000-8000-000000002001', '00000000-0000-4000-8000-000000001001', 'Цагаан товчтой цамц', 'Шошготой, шинэ цагаан цамц. 100% хөвөн, индүүдэхэд амархан.', 35000, 'M', 'new', true, true, '2026-10-29T11:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003027', '00000000-0000-4000-8000-000000002001', '00000000-0000-4000-8000-000000001008', 'Тэмээн өнгийн сүлжмэл малгай', 'Тэмээн бор өнгийн дулаан сүлжмэл малгай.', 15000, 'Нэг хэмжээ', 'excellent', true, true, '2026-10-29T10:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003028', '00000000-0000-4000-8000-000000002004', '00000000-0000-4000-8000-000000001002', 'Цөцгий өнгийн свитшот', 'Шошготой, шинэ цөцгий өнгийн свитшот. 100% хөвөн.', 42000, 'S', 'new', true, true, '2026-10-29T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003029', '00000000-0000-4000-8000-000000002001', '00000000-0000-4000-8000-000000001004', 'Хаки hoodie', 'Хаки ногоон өнгийн оверсайз hoodie. Ханцуйн үзүүрт бага зэрэг элэгдэлтэй.', 55000, 'L', 'good', true, true, '2026-10-29T08:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003030', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001001', 'Хар саарал футболк', 'Хар саарал өнгийн энгийн футболк. Нэг удаа өмссөн.', 25000, 'L', 'excellent', true, true, '2026-10-29T07:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003031', '00000000-0000-4000-8000-000000002005', '00000000-0000-4000-8000-000000001004', 'Хар hoodie', 'Сонгодог хар hoodie. Аливаа хувцастай зохицно.', 57000, 'L', 'good', true, true, '2026-10-29T06:00:00.000Z'),
  ('00000000-0000-4000-8000-000000003032', '00000000-0000-4000-8000-000000002003', '00000000-0000-4000-8000-000000001006', 'Хар арьсан челси гутал', 'Гялгар хар арьсан челси гутал. Хэмжээ EU 41.', 110000, '41', 'excellent', false, true, '2026-10-29T05:00:00.000Z')
on conflict (id) do nothing;

